package com.booksyde.service;
import com.booksyde.dto.request.*; import com.booksyde.dto.response.*; import com.booksyde.entity.MangaEntity; import com.booksyde.exception.*; import com.booksyde.mapper.BookMapper; import com.booksyde.repository.MangaRepository; import com.booksyde.security.BooksydeRole; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class BookService {private final MangaRepository repo; public BookService(MangaRepository repo){this.repo=repo;} @Transactional(readOnly=true) public List<BookResponse> publicBooks(){return repo.findAllByVisibilityOrderByCreatedAtDesc("public").stream().map(BookMapper::toResponse).toList();} @Transactional(readOnly=true) public BookResponse find(UUID id,UUID userId,Set<BooksydeRole> roles){MangaEntity e=get(id); ensureRead(e,userId,roles); return BookMapper.toResponse(e);} @Transactional(readOnly=true) public List<BookResponse> owned(UUID userId,Set<BooksydeRole> roles){if(roles.contains(BooksydeRole.ADMIN)) return repo.findAll().stream().map(BookMapper::toResponse).toList(); return repo.findAllByCreatorIdOrderByCreatedAtDesc(userId).stream().map(BookMapper::toResponse).toList();} @Transactional public BookResponse create(CreateBookRequest r,UUID userId,Set<BooksydeRole> roles){if(!(roles.contains(BooksydeRole.ADMIN)||roles.contains(BooksydeRole.PUBLISHER)||roles.contains(BooksydeRole.CREATOR))) throw new ForbiddenException("Conta sem permissão para criar obras."); if(repo.findBySlug(r.slug()).isPresent()) throw new BusinessException("Slug já utilizado."); String visibility=r.visibility()==null?"private":r.visibility(); if("public".equals(visibility)&&!roles.contains(BooksydeRole.ADMIN)) visibility="private"; MangaEntity e=new MangaEntity(r.title(),nz(r.author()),nz(r.category()),nz(r.description()),nz(r.synopsis()),r.workType(),userId,r.slug(),visibility,r.collection(),r.coverUrl(),r.priceCents(),nzDefault(r.distributionChannel(),"unlisted")); return BookMapper.toResponse(repo.save(e));} @Transactional public BookResponse update(UUID id,UpdateBookRequest r,UUID userId,Set<BooksydeRole> roles){MangaEntity e=get(id); ensureOwner(e,userId,roles); String visibility=r.visibility()==null?e.getVisibility():r.visibility(); if("public".equals(visibility)&&!roles.contains(BooksydeRole.ADMIN)) visibility=e.getVisibility(); e.update(r.title(),nz(r.author()),nz(r.category()),nz(r.description()),nz(r.synopsis()),visibility,r.coverUrl(),r.priceCents(),nzDefault(r.distributionChannel(),e.getDistributionChannel())); return BookMapper.toResponse(e);} @Transactional public void delete(UUID id,UUID userId,Set<BooksydeRole> roles){MangaEntity e=get(id); ensureOwner(e,userId,roles); repo.delete(e);} public MangaEntity get(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Obra não encontrada."));} public void ensureOwner(MangaEntity e,UUID userId,Set<BooksydeRole> roles){if(!roles.contains(BooksydeRole.ADMIN)&&!userId.equals(e.getCreatorId())) throw new ForbiddenException("Você não possui acesso a esta obra.");} private void ensureRead(MangaEntity e,UUID userId,Set<BooksydeRole> roles){if(!"public".equals(e.getVisibility())) ensureOwner(e,userId,roles);} private static String nz(String s){return s==null?"":s.trim();} private static String nzDefault(String s,String d){return s==null||s.isBlank()?d:s.trim();}}
